import { createRouter, createWebHistory } from 'vue-router'
// main
import StartPage from '@/views/main/startPage.vue'
import NotFound from '@/views/main/pageNotFound.vue'
// activity
import MainActivity from '@/views/activity/mainActivity.vue'
import acMenuMain from '@/views/activity/mainMenu.vue'
// audit
import MainAudit from '@/views/audit/mainAudit.vue'
// equipment
import MainEquipment from '@/views/equipment/mainEquipment.vue'
import eqMainStart from '@/views/equipment/mainStart.vue'
import eqStoreMenu from '@/views/equipment/store/storeMenu.vue'
// import eqStorePage from '@/views/equipment/store/storePage.vue'
import eqMyMenu from '@/views/equipment/my/myMenu.vue'
// import eqMyPage from '@/views/equipment/my/myPage.vue'
import eqReportMenu from '@/views/equipment/report/reportMenu.vue'
// import eqReportPage from '@/views/equipment/report/reportPage.vue'
// form
import MainForm from '@/views/form/mainForm.vue'
// access
import MainAccess from '@/views/access/mainAccess.vue'
// accident
import MainAccident from '@/views/accident/mainAccident.vue'

const routes = [
  {
    path: '/',
    name: 'StartPage',
    component: StartPage,
    meta: {
      requiresAuth: true,
      title: 'SAA Home'
    }
  },
  {
    path: '/activity/',
    name: 'MainActivity',
    component: MainActivity,
    meta: {
      requiresAuth: true,
      title: 'Activity Home'
    },
    children: [
      {
        path: 'menu',
        name: 'acMenuMain',
        meta: {
          requiresAuth: true,
          title: 'Activity Menu'
        },
        components: {
          safety_activity_body: acMenuMain
        }
      }
    ]
  },
  {
    path: '/audit',
    name: 'MainAudit',
    component: MainAudit,
    meta: {
      requiresAuth: true,
      title: 'Audit Home'
    }
  },
  {
    path: '/equipment/',
    name: 'MainEquipment',
    component: MainEquipment,
    meta: {
      requiresAuth: true,
      title: 'SE Home'
    },
    children: [
      {
        path: 'start',
        name: 'eqMainStart',
        meta: {
          requiresAuth: true,
          title: 'SE Start'
        },
        components: {
          sub_body: eqMainStart
        }
      },
      {
        path: 'storemenu',
        name: 'eqStoreMenu',
        meta: {
          requiresAuth: true,
          title: 'SE Store Menu'
        },
        components: {
          sub_body: eqStoreMenu
        }
      },
      {
        path: 'mymenu',
        name: 'eqMyMenu',
        meta: {
          requiresAuth: true,
          title: 'SE My Menu'
        },
        components: {
          sub_body: eqMyMenu
        }
      },
      {
        path: 'reportmenu',
        name: 'eqReportMenu',
        meta: {
          requiresAuth: true,
          title: 'SE Report Menu'
        },
        components: {
          sub_body: eqReportMenu
        }
      }
    ]
  },
  {
    path: '/form',
    name: 'MainForm',
    component: MainForm,
    meta: {
      requiresAuth: true,
      title: 'Form Home'
    }
  },
  {
    path: '/access',
    name: 'MainAccess',
    component: MainAccess,
    meta: {
      requiresAuth: true,
      title: 'Access Home'
    }
  },
  {
    path: '/accident',
    name: 'MainAccident',
    component: MainAccident,
    meta: {
      requiresAuth: true,
      title: 'Accident Home'
    }
  },
  {
    path: '/:pathMatch(.*)*',
    name: 'not_found',
    component: NotFound,
    meta: { title: 'NotFound', requiresAuth: false }
  }
]

const router = createRouter({
  history: createWebHistory(process.env.BASE_URL),
  routes
})
const DEFAULT_TITLE = 'Safety Activity Apps'
router.beforeEach((to, from, next) => {
  document.title = to.meta.title || DEFAULT_TITLE
  next()
})

export default router
