<script setup>
import { computed, inject, defineProps } from 'vue'
const goToRouteName = inject('goToRouteName')

const props = defineProps({
  title: {
    type: String,
    required: true
  },
  color: {
    type: String,
    required: true
  },
  icon: {
    type: String,
    required: true
  },
  theme: {
    type: String,
    required: true
  },
  go_route: {
    type: String,
    required: true
  },
  go_home: {
    type: String,
    required: true
  }
})

const isReady = computed(() =>
  ['title', 'color', 'icon', 'theme', 'go_route', 'go_home'].every((key) => {
    const v = props[key]
    return v !== undefined && v !== null && String(v).trim() !== ''
  })
)

const colorMap = {
  sky: 'bg-sky-400',
  orange: 'bg-orange-400',
  gray: 'bg-gray-400',
  rose: 'bg-rose-400',
  blue: 'bg-blue-400',
  purple: 'bg-purple-400'
}

</script>
<template>
  <nav
    v-show="isReady"
    class="navbar navbar-expand-sm sticky-top p-0"
    :data-bs-theme="props.theme"
  >
    <div :class="['m-0', 'w-full', 'p-2', colorMap[props.color] ]">
      <div
        class="relative flex items-center justify-between p-2"
        style="height: 6vh"
      >
        <div class="absolute inset-y-0 left-0 flex items-center sm:hidden">
          <a
            class="navbar-brand py-2"
            v-on:click="goToRouteName(props.go_route)"
            ><label class="cursor-pointer font-bold text-xl ps-2">{{
              props.title
            }}</label></a
          >
        </div>
        <div
          class="flex flex-1 items-center justify-center sm:items-stretch sm:justify-start"
        >
          <div class="hidden sm:ml-3 sm:block">
            <div class="flex shrink-0 items-center">
              <a
                class="navbar-brand p-0"
                v-on:click="goToRouteName(props.go_route)"
                ><i :class="`bi ${props.icon} text-2xl mx-1`"></i
                ><label
                  class="cursor-pointer font-bold text-xl"
                  >{{ props.title }}</label
                ></a
              >
            </div>
          </div>
        </div>
        <div
          class="absolute inset-y-0 right-0 flex items-center pe-1 sm:static sm:inset-auto sm:ml-6 sm:pr-0"
        >
          <button type="button" class="btn btn-sm btn-dark" disabled>
            <template v-if="$store.getters.getTypeCompany ?? ''"
              ><strong class="text-uppercase">{{
                $store.getters.getTypeCompany
              }}</strong></template
            >
            <template v-else><i class="bi bi-person-fill-slash"></i></template>
          </button>
          <button type="button" class="btn btn-sm btn-light mx-1" disabled>
            <i class="bi bi-person-circle me-1"></i
            ><strong>{{ $store.getters.get_eid }}</strong>
          </button>
          <button
            type="button"
            class="btn btn-sm btn-danger rounded-circle"
            v-on:click="goToRouteName(props.go_home)"
          >
            <i class="bi bi-house-fill"></i>
          </button>
        </div>
      </div>
    </div>
  </nav>
</template>
