<script setup>
import { inject, onMounted, ref } from 'vue'
import { animate, splitText, stagger, createTimeline } from 'animejs'
const goToRouteName = inject('goToRouteName')
const showTogle = ref(true)
const anime1 = ref(null)
const anime2 = ref(null)
const anime3 = ref(null)

onMounted(() => {
  goToRouteName('eqMainStart')

  splitText(anime1.value, {
    words: { wrap: 'clip' }
  }).addEffect(({ words }) =>
    animate(words, {
      y: [{ to: ['100%', '0%'] }, { to: '-100%', delay: 750, ease: 'in(3)' }],
      duration: 750,
      ease: 'out(3)',
      delay: stagger(100),
      loop: true
    })
  )

  splitText(anime2.value, {
    chars: { wrap: true }
  }).addEffect(({ chars }) =>
    animate(chars, {
      y: ['75%', '0%'],
      duration: 750,
      ease: 'out(3)',
      delay: stagger(50),
      loop: true,
      alternate: true
    })
  )

  splitText(anime3.value, {
    chars: {
      wrap: 'clip',
      clone: 'bottom'
    }
  }).addEffect(({ chars }) =>
    createTimeline().add(
      chars,
      {
        y: '-100%',
        loop: true,
        loopDelay: 350,
        duration: 750,
        ease: 'inOut(2)'
      },
      stagger(150, { from: 'center' })
    )
  )
})
</script>
<style scoped>
.container-sm {
  position: relative;
  width: 304px; /* ตรงกับ viewBox width */
  height: 112px; /* ตรงกับ viewBox height */
}

#svg-createmotionpath {
  position: relative;
}

#svg-createmotionpath .car {
  position: absolute;
  width: 16px;
  height: 8px;
  left: -8px;
  top: -5px;
  color: #fff;
}

#svg-createmotionpath .docs-demo-template .car {
  display: none;
}
</style>

<template>
  <div class="w-100">
    <div>
      <NavTopBar
        title="Safety Equipment"
        color="orange"
        icon="bi-person-bounding-box"
        theme="dark"
        go_route="eqMainStart"
        go_home="StartPage"
      />
    </div>
    <div style="position: relative; height: 91vh; overflow-y: auto" id="menuEquipMain">
      <div v-if="showTogle">
        <div class="row m-0">
          <div class="col-12 col-md-6 my-2 mx-0 px-5">
            <div
              class="card shadow-sm"
              data-intro="หน้าจัดการคลังภาค,จังหวัด,ส่วนงาน"
              data-step="1"
            >
              <div class="card-body p-0">
                <div
                  v-if="$store.getters.ac_stroe != ''"
                  v-on:click="[
                    goToRouteName('eqStoreMenu'),
                    (showTogle = false)
                  ]"
                >
                  <div
                    class="bg-sky-400 cursor-pointer m-0 py-2 hover:scale-105"
                    ref="anime1"
                  >
                    <i class="bi bi-house-fill"></i
                    ><strong class="mx-1">Store</strong
                    ><span class="badge text-bg-info rounded-pill"
                      >ST{{ $store.getters.ac_stroe }}</span
                    ><span class="badge text-bg-primary rounded-pill">{{
                      $store.getters.val_re_st
                    }}</span
                    ><span class="badge text-bg-dark rounded-pill">{{
                      $store.getters.val_rq_re_st
                    }}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <div class="col-12 col-md-6 my-2 px-5">
            <div
              class="card shadow-sm"
              data-intro="ข้อมูลอุปกรณ์ส่วนบุคคล"
              data-step="2"
            >
              <div class="card-body p-0">
                <div
                  v-on:click="[goToRouteName('eqMyMenu'), (showTogle = false)]"
                >
                  <div
                    class="bg-emerald-400 cursor-pointer m-0 py-2 hover:scale-105"
                    ref="anime2"
                  >
                    <i class="bi bi-person-fill"></i
                    ><strong class="mx-1">My Equipment</strong>
                    <span
                      class="badge text-bg-primary rounded-pill"
                      v-if="$store.getters.val_re_my != ''"
                      >{{ $store.getters.val_re_my }}</span
                    >
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div class="row m-0">
          <div class="col-12 col-md-12 mb-2 px-5">
            <div class="card shadow-sm" data-intro="รายงานต่างๆ" data-step="3">
              <div class="card-body p-0">
                <div
                  v-on:click="[
                    goToRouteName('eqReportMenu'),
                    (showTogle = false)
                  ]"
                >
                  <div
                    class="bg-amber-300 cursor-pointer m-0 py-2 hover:scale-105"
                    ref="anime3"
                  >
                    <i class="bi bi-files"></i
                    ><strong class="mx-1">Report</strong>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="row m-0">
        <div class="col-12 p-0">
          <router-view name="sub_body" />
        </div>
      </div>
    </div>
    <nav class="navbar navbar-expand-sm py-0 fixed-bottom">
      <div class="container-fluid" id="collapseDown">
        <span class="navbar-text text-end w-100">
          <button
            type="button"
            class="btn btn-light"
            @click="[showTogle = !showTogle,goToRouteName('eqMainStart')]"
            :disabled="showTogle"
          >
            <i
              :class="
                'bi bi-caret-' + (showTogle == true ? 'up' : 'down') + '-fill'
              "
            ></i>
          </button>
        </span>
      </div>
    </nav>
  </div>
</template>
