<template>
  <div>
    <div class="d-grid gap-2 d-md-block mt-2 text-start">
      <button
        v-for="(it, idx) in items"
        :key="idx"
        class="btn mx-1 mt-1 shadow-sm"
        :class="btnClass(it)"
      >
        <i :class="['bi', it.icon, 'me-1']"></i>
        <span v-if="it.label">{{ it.label }}</span>
        <span v-else v-html="it.htmlLabel"></span>
        <span
          v-if="it.badge && it.badge.value !== ''"
          class="badge rounded-pill ms-1"
          :class="badgeClass(it.badge.type)"
        >
          {{ it.badge.value }}
        </span>
      </button>
    </div>
  </div>
</template>
<script setup>
import { computed } from 'vue'
import { useStore } from 'vuex'
const store = useStore()
const items = computed(() => [
  {
    icon: 'bi-person-add',
    label: 'อุปกรณ์ที่ส่งถึงฉัน',
    badge: { type: 'light', value: store.getters.val_re_my },
    variant: 'success'
  },
  {
    icon: 'bi-person-fill-gear',
    label: 'อุปกรณ์ของฉัน',
    variant: 'light'
  },
  {
    icon: 'bi-person-bounding-box',
    label: 'Size ของฉัน',
    variant: 'success'
  },
  {
    icon: 'bi-person-plus-fill',
    label: 'ขออุปกรณ์',
    variant: 'light'
  },
  {
    icon: 'bi-person-exclamation',
    label: 'รายการขออุปกรณ์',
    variant: 'success'
  },
  {
    icon: 'bi-person-fill-check',
    label: 'ตรวจสอบอุปกรณ์',
    variant: 'light'
  },
  {
    icon: 'bi-person-lock',
    label: 'รายการตรวจสอบอุปกรณ์',
    variant: 'success'
  }
])
const btnClass = (it) => {
  return `btn btn-${it.variant ?? 'light'} mx-1 mt-1 shadow-sm border`
}

const badgeClass = (type) => {
  return `text-bg-${type}`
}
</script>
